pyenv_normalize_install_lang() {
  raw="$(printf '%s' "$1" | tr '[:upper:]' '[:lower:]' | tr '_' '-')"
  case "$raw" in
    zh|zh-cn|zh-hans|zh-hans-cn|zh-sg|zh-tw|zh-hant|zh-hant-tw|zh-hk|zh-mo) printf 'zh-CN' ;;
    pt|pt-pt|pt-br) printf 'pt-BR' ;;
    en|en-us|en-gb|en-au|en-ca|'') printf 'en-US' ;;
    es|es-mx|es-ar|es-es|es-419) printf 'es' ;;
    ja|ko|fr|de|ru|fa|ar|hi|it|tr) printf '%s' "$raw" ;;
    *) printf 'en-US' ;;
  esac
}

pyenv_install_tr() {
  key="$1"
  lang="$(pyenv_normalize_install_lang "${PYENV_INSTALL_LANG:-en-US}")"
  case "$lang:$key" in
    en-US:install-cancelled) printf %s 'Install cancelled.' ;;
    en-US:install-continue) printf %s 'Continue with install? [y/N]:' ;;
    en-US:install-done) printf %s 'pyenv-native installed. Open a new terminal, then run `pyenv doctor`.' ;;
    en-US:install-downloading) printf 'Downloading %s' "$2" ;;
    en-US:install-extracting) printf %s 'Extracting release bundle' ;;
    en-US:install-failed) printf %s 'Installation failed' ;;
    en-US:install-installed-command) printf 'Installed command: %s' "$2" ;;
    en-US:install-installed-gui) printf 'Installed GUI: %s' "$2" ;;
    en-US:install-installed-mcp) printf 'Installed MCP server: %s' "$2" ;;
    en-US:install-installed-to) printf 'Installed pyenv-native to %s' "$2" ;;
    en-US:install-installing) printf 'Installing into %s' "$2" ;;
    en-US:install-lang-help) printf %s 'Interface language for installer messages' ;;
    en-US:install-log-file) printf 'Log file: %s' "$2" ;;
    en-US:install-mcp-helper) printf 'MCP config helper: %s' "$2" ;;
    en-US:install-need-yes) printf %s 'Confirmation is required for interactive installs. Re-run with --yes for non-interactive use.' ;;
    en-US:install-need-yes-pwsh) printf %s 'Confirmation is required for interactive installs. Re-run with -Yes for non-interactive use.' ;;
